  wallets:{group:'Malware & crypto', name:'Crypto address formats', icon:'bitcoin', note:'Patterns help spot addresses; validate the checksum before acting. Patterns are approximate.', rows:[
    ['1… (P2PKH)','Bitcoin legacy','Base58, starts with 1, 26–35 chars.','^1[1-9A-HJ-NP-Za-km-z]{25,34}$','',0,'btc, bitcoin, legacy'],
    ['3… (P2SH)','Bitcoin script','Base58, starts with 3, 26–35 chars (multisig, wrapped SegWit).','^3[1-9A-HJ-NP-Za-km-z]{25,34}$','',0,'btc, p2sh'],
    ['bc1q…','Bitcoin SegWit (bech32)','Lowercase bech32; 42 chars (P2WPKH) or 62 (P2WSH).','^bc1q[02-9ac-hj-np-z]{38,58}$','',0,'btc, bech32, segwit'],
    ['bc1p…','Bitcoin Taproot','bech32m, 62 chars.','^bc1p[02-9ac-hj-np-z]{58}$','',0,'btc, taproot'],
    ['tb1… / m… / n…','Bitcoin testnet','Testnet addresses.','Not real value — but seen in tests and scams.','',0,'testnet'],
    ['0x + 40 hex','Ethereum / EVM','Same format on Ethereum, BNB Chain, Polygon, Arbitrum, Base…','^0x[a-fA-F0-9]{40}$ — mixed case is an EIP-55 checksum. Check every EVM chain.','',0,'eth, ethereum, bsc, polygon, usdt, erc20'],
    ['4… (95 chars)','Monero','Base58, 95 chars (subaddresses start with 8; integrated addresses 106 chars).','^[48][1-9A-HJ-NP-Za-km-z]{94}$ — favoured by ransomware and miners; transactions are hard to trace on-chain.','T1496',1,'xmr, monero'],
    ['T… (34 chars)','TRON','Base58, starts with T, 34 chars.','^T[1-9A-HJ-NP-Za-km-z]{33}$ — USDT-TRC20 is common in scams.','',0,'trx, tron, usdt, trc20'],
    ['Solana (Base58, 32–44)','Solana','Base58 public key, no fixed prefix.','[1-9A-HJ-NP-Za-km-z]{32,44} — high false-positive rate; confirm on an explorer.','',0,'sol'],
    ['L… / M… / ltc1…','Litecoin','Legacy L/M Base58, or ltc1 bech32.','','',0,'ltc, litecoin'],
    ['D… (34 chars)','Dogecoin','Base58, starts with D.','','',0,'doge'],
    ['bitcoincash:q…','Bitcoin Cash','CashAddr format (prefix often omitted).','','',0,'bch'],
    ['r… (25–35 chars)','XRP','Ripple Base58 alphabet; often with a destination tag.','Exchanges need the tag — note it too.','',0,'xrp, ripple'],
    ['t1… / zs1…','Zcash','t1 = transparent, zs1 = shielded (private).','Shielded transfers cannot be followed.','',0,'zec, zcash'],
    ['addr1…','Cardano','Shelley bech32 address.','','',0,'ada, cardano'],
    ['EQ… / UQ… (48 chars)','TON','Base64url user-friendly address.','Seen in Telegram-based scams.','',0,'ton, telegram'],
    ['xpub / ypub / zpub','Extended public key','Derives every address of a wallet.','Exposure reveals the full wallet history (not the funds).','',0,'hd, wallet'],
    ['5… / K… / L… (51–52 chars)','Bitcoin WIF private key','Wallet Import Format private key.','Finding one means the funds can be taken. Handle as a secret.','T1552',1,'private, key, wif'],
    ['12 / 24 words','Seed phrase (BIP-39)','Mnemonic that restores a wallet.','Infostealers hunt for these; treat as a secret.','T1552.001',1,'mnemonic, recovery, phrase'],
    ['*.eth','ENS name','Ethereum Name Service name pointing to an address.','Resolve to the address; names give attribution clues.','',0,'ens']]},
  ransom:{group:'Malware & crypto', name:'Ransomware tell-tales', icon:'lock', note:'Generic patterns. Identify a family with ID Ransomware or No More Ransom using a note and a sample file.', rows:[
    ['Ransom note files','Notes in every folder','README/HOW_TO_DECRYPT/RESTORE-style .txt or .html files.','Note name and Tox/onion contacts identify the family.','T1486',1,'readme, decrypt'],
    ['Appended extension','New file extension','Encrypted files get a fixed or random/victim-ID extension.','The extension plus note style narrows the family.','T1486',1,'extension'],
    ['vssadmin delete shadows','Backup deletion','Removes shadow copies (also wmic shadowcopy delete, wbadmin, bcdedit recovery off).','Usually minutes before encryption — treat as an emergency.','T1490',1,'shadow, copies'],
    ['Mass service stop','Service kill list','Stops SQL, Exchange, backup and AV services so files are unlocked.','net stop / sc stop bursts; 7036 events in bulk.','T1489',1,'net, stop'],
    ['Exfil tools','Data theft before encryption','rclone, MEGAsync, WinSCP, restic, FileZilla used for double extortion.','rclone.conf in user folders, large outbound transfers in SRUM/firewall logs.','T1567.002',1,'rclone, mega, double, extortion'],
    ['Tox ID (76 hex)','Tox chat contact','Tox IDs are 76 hex characters; common in notes.','Pivot the ID in threat intel.','',0,'tox, qtox'],
    ['.onion URL','Tor negotiation site','Notes link to Tor chat or leak sites.','Record but do not visit from corporate networks.','',0,'tor, onion'],
    ['bcdedit /set safeboot','Safe Mode reboot','Reboots into Safe Mode where AV may not run.','safeboot network + reboot.','T1562.009',1,'safe, mode'],
    ['Wallpaper change','Desktop defacement','Wallpaper replaced with the ransom message.','HKCU\\Control Panel\\Desktop\\Wallpaper set to an image in Temp.','T1491.001',0,'wallpaper'],
    ['GPO deployment','Mass deployment by GPO','A new GPO pushes the encryptor or a task to all hosts.','5136 on GPOs; new scheduled tasks everywhere at once.','T1484.001',1,'group, policy'],
    ['PsExec mass execution','Mass deployment by PsExec','PsExec/WMI with a host list.','7045 PSEXESVC on many hosts in minutes.','T1569.002',1,'psexec'],
    ['ESXi targeting','Hypervisor encryption','.vmdk/.vmx files encrypted after esxcli vm process kill.','SSH enabled on ESXi, unusual shell logins.','T1486',1,'vmware, esxi'],
    ['BYOVD EDR killers','Vulnerable driver loading','Signed but vulnerable drivers used to kill security tools.','New driver services, Sysmon 6 with known-vulnerable drivers.','T1562.001',1,'edr, killer, driver'],
    ['Intermittent encryption','Partial encryption','Only parts of each file are encrypted for speed.','Files may be partly recoverable; entropy is uneven.','T1486',0,'partial']]},
